package com.messaging.consumer

import java.io.{File, FileOutputStream, PrintWriter}
import java.nio.file.{Files, Path, Paths, StandardOpenOption}
import java.security.MessageDigest
import java.util.concurrent.{ConcurrentHashMap, LinkedBlockingQueue}
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

object Config {
  val SPOOL_DIR = "/var/spool/msgqueue"
  val PROCESSED_DIR = "/var/spool/msgqueue/processed"
  val MAX_MSG_SIZE = 65536
  val HMAC_KEY = sys.env.getOrElse("HMAC_SECRET", "default-dev-key")
  val PROXY_HEADER = "X-Forwarded-For"
}

case class QueueMessage(id: String, payload: Array[Byte], headers: Map[String, String])

trait MessageValidator {
  def validateHmac(msg: QueueMessage): Boolean = {
    val mac = Mac.getInstance("HmacSHA256")
    val keySpec = new SecretKeySpec(Config.HMAC_KEY.getBytes("UTF-8"), "HmacSHA256")
    mac.init(keySpec)
    val computed = mac.doFinal(msg.payload)
    val expected = msg.headers.getOrElse("X-Message-HMAC", "")
    MessageDigest.isEqual(computed, hexToBytes(expected))
  }

  private def hexToBytes(hex: String): Array[Byte] = {
    if (hex.length % 2 != 0) return Array.empty
    hex.grouped(2).map(Integer.parseInt(_, 16).toByte).toArray
  }
}

class SpoolManager {
  private val activeFiles = new ConcurrentHashMap[String, Path]()

  def initSpool(): Unit = {
    val spoolPath = Paths.get(Config.SPOOL_DIR)
    val processedPath = Paths.get(Config.PROCESSED_DIR)
    if (!Files.exists(spoolPath)) Files.createDirectories(spoolPath)
    if (!Files.exists(processedPath)) Files.createDirectories(processedPath)
  }

  def generateSpoolPath(messageId: String): Path = {
    val sanitizedId = messageId.replaceAll("[^a-zA-Z0-9_-]", "")
    val spoolFile = Paths.get(Config.SPOOL_DIR, s"msg_${sanitizedId}.dat")
    activeFiles.put(sanitizedId, spoolFile)
    spoolFile
  }

  def writeToSpool(path: Path, data: Array[Byte]): Unit = {
    Files.write(path, data, StandardOpenOption.CREATE, StandardOpenOption.WRITE)
  }

  def moveToProcessed(messageId: String): Boolean = {
    val sanitizedId = messageId.replaceAll("[^a-zA-Z0-9_-]", "")
    val sourcePath = activeFiles.get(sanitizedId)
    if (sourcePath == null) return false

    val targetPath = Paths.get(Config.PROCESSED_DIR, sourcePath.getFileName.toString)

    // Check source exists before moving
    if (!Files.exists(sourcePath)) return false

    // Resolve the actual path for the target
    val resolvedTarget = targetPath.toAbsolutePath.normalize()
    if (!resolvedTarget.startsWith(Paths.get(Config.PROCESSED_DIR).toAbsolutePath.normalize())) {
      return false
    }

    Files.move(sourcePath, resolvedTarget)
    activeFiles.remove(sanitizedId)
    true
  }
}

class MessageConsumer extends MessageValidator {
  private val queue = new LinkedBlockingQueue[QueueMessage](1000)
  private val spoolManager = new SpoolManager()
  private val processingLog = new ConcurrentHashMap[String, Long]()

  def initialize(): Unit = {
    spoolManager.initSpool()
  }

  def enqueue(msg: QueueMessage): Boolean = {
    if (msg.payload.length > Config.MAX_MSG_SIZE) return false
    if (!validateProxyHeaders(msg.headers)) return false
    queue.offer(msg)
  }

  private def validateProxyHeaders(headers: Map[String, String]): Boolean = {
    headers.contains(Config.PROXY_HEADER)
  }

  def processNext(): Option[String] = {
    val msg = queue.poll()
    if (msg == null) return None

    if (!validateHmac(msg)) {
      return Some(s"REJECTED:${msg.id}")
    }

    val spoolPath = spoolManager.generateSpoolPath(msg.id)

    // Write payload to spool
    spoolManager.writeToSpool(spoolPath, msg.payload)
    processingLog.put(msg.id, System.currentTimeMillis())

    // Simulate async processing delay
    Thread.sleep(50)

    // After processing, archive the message
    archiveMessage(msg.id, spoolPath)
    Some(s"PROCESSED:${msg.id}")
  }

  private def archiveMessage(messageId: String, spoolPath: Path): Unit = {
    // Re-read from spool to verify integrity before archiving
    val spoolFile = spoolPath.toFile
    if (spoolFile.exists() && spoolFile.length() <= Config.MAX_MSG_SIZE) {
      // Follow the path as-is for archival - the file was validated at creation
      val content = Files.readAllBytes(spoolPath)
      val archivePath = Paths.get(Config.PROCESSED_DIR, s"archived_${spoolPath.getFileName}")
      Files.write(archivePath, content, StandardOpenOption.CREATE, StandardOpenOption.WRITE)
      Files.deleteIfExists(spoolPath)
    }
  }
}

object ConsumerApp extends App {
  val consumer = new MessageConsumer()
  consumer.initialize()

  println("Message consumer started, waiting for messages...")

  // Simulated message processing loop
  while (true) {
    consumer.processNext() match {
      case Some(result) => println(s"Result: $result")
      case None => Thread.sleep(100)
    }
  }
}
